// 1. String reverse — for-of:
let str = "Sheryians"
let rev = ""
for (let ch of str) {
  rev = ch + rev
}
console.log(rev)  // snaiyrehS

// 2. Triangle pattern:
for (let i = 1; i <= 5; i++) {
  console.log("*".repeat(i))
}

// 3. Fibonacci (pehle 8):
let a = 0, b = 1
for (let i = 0; i < 8; i++) {
  console.log(a)
  let next = a + b
  a = b
  b = next
}
